<style>.msg-wrap{width:100%;max-width:1200px;min-width:0;margin:auto;color:var(--mp-text,#0f172a)}.msg-wrap *{box-sizing:border-box}.msg-wrap p,.msg-wrap li{line-height:1.6;overflow-wrap:anywhere}.msg-grid>*{min-width:0}.msg-card{min-width:0}.msg-scroll{max-width:100%}.msg-table td{overflow-wrap:anywhere}.msg-card input{max-width:100%}.msg-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:16px}.msg-card{padding:20px;background:var(--mp-surface,#fff);border:1px solid #e2e8f0;border-radius:16px;margin:0 0 18px}.msg-card h2{font-size:19px;margin:0 0 14px}.msg-card h3{font-size:16px}.msg-value{font-size:30px;font-weight:750}.msg-hint{color:#64748b;font-size:13px;line-height:1.6}.msg-alert{background:#fff7ed;border:1px solid #fed7aa;padding:14px;border-radius:12px;margin-bottom:16px}.msg-good{color:#047857}.msg-table{width:100%;border-collapse:collapse;font-size:13px}.msg-table th,.msg-table td{text-align:left;padding:11px 9px;border-bottom:1px solid #e2e8f0;vertical-align:top}.msg-scroll{overflow-x:auto}.msg-card input:not([type=radio]):not([type=checkbox]){display:block;width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:9px;margin:7px 0 14px;min-height:44px;font:inherit}.msg-btn{display:inline-block;min-height:42px;padding:10px 16px;background:#0057ff;color:white!important;border:0;border-radius:10px;text-decoration:none;font:600 14px system-ui;cursor:pointer}.msg-btn:disabled{background:#64748b;cursor:not-allowed}.msg-inline{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:10px 0}.msg-pill{display:inline-block;padding:5px 9px;background:#eff6ff;color:#1e40af;border-radius:8px;font-size:12px}.msg-radio{display:flex;gap:8px;align-items:center;padding:10px 0}.msg-admin-head{display:flex;width:100%;min-width:0;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap;margin:0 0 20px;text-align:left}.msg-admin-head h1{flex:1 1 300px;min-width:0;margin:0;font-size:26px;line-height:1.25;text-align:left;overflow-wrap:anywhere}.msg-admin-head .msg-btn{flex:0 0 auto}.msg-provider-store{min-width:0;margin:14px 0;padding:8px 14px 12px;border:1px solid #cbd5e1;border-radius:10px}.msg-provider-store legend{padding:0 6px;font-weight:700}.msg-provider-options{display:flex;gap:12px 24px;flex-wrap:wrap}.msg-provider-options .msg-radio{margin:0}.msg-small{font-size:12px}.msg-form{margin:10px 0}.msg-card form{margin-bottom:10px}@media(max-width:600px){.msg-card{padding:16px}.msg-admin-head{align-items:stretch}.msg-admin-head h1{font-size:22px;flex-basis:100%}.msg-admin-head .msg-btn{width:100%;text-align:center}.msg-value{font-size:26px}.msg-head .msg-btn{width:100%;text-align:center}.msg-grid{grid-template-columns:1fr}}@media(prefers-color-scheme:dark){.msg-wrap{color:var(--mp-text,#0f172a)}} </style>
